UPDATE companies SET description='Andersen Self-Service Auto Parts operates from Kearney, Nebraska, where it has been based since 1960. The business traces its roots to 1937, when Ray Andersen founded Andersen Wrecking in downtown Gibbon, Nebraska. After relocating to Kearney, the company expanded into metals and vehicle purchasing, later acquiring Stan’s Auto Parts in 1989 to launch Andersen Auto Parts, a discount outlet for classic and older-model vehicle components.

In 2009, the company transformed its property into a self-service facility, crushing roughly 1,400 vehicles to make room for an inventory that now exceeds 1,700 cars, trucks, campers, and motorcycles. Customers bring their own tools and remove the parts they need, a model that allows the company to offer prices up to 80 percent below conventional auto-parts retailers. The inventory spans vehicles from the 1940s through the mid-2000s.

The shift to self-service was driven by a desire to pass maximum savings to customers; by eliminating the labor cost of part removal, the company can maintain low prices while keeping the facility clean, organized, and safe.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Self-service parts removal", "Parts interchange assistance", "Used auto parts retail", "Used motorcycle parts retail"], "industries": ["Automotive aftermarket", "Motorcycle parts", "Classic car restoration"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Self-service parts removal passes savings to customers", "Over 1,700 vehicles and motorcycles on site", "Parts interchange assistance ensures correct part identification", "Clean, organized, and safe facility", "Inventory spans 1940s to mid-2000s vehicles"], "facts_used": ["Founded 1937 by Ray Andersen in Gibbon, Nebraska -> /about-us", "Moved to Kearney, Nebraska in 1960 -> /about-us", "Purchased Stan''s Auto Parts in 1989 -> /about-us", "Renovated property for self-service model in 2009, crushed 1,400 vehicles, set up 1,700+ vehicles -> /about-us", "Grand opening 2011 -> /about-us", "Address: 2045 25 RD, Kearney NE 68847 -> /", "Hours: M-F 8am-5:30pm, Sat 8am-4pm -> /", "Self-service model passes savings to customers -> /", "Parts interchange assistance -> /", "Clean, organized, safe facility -> /", "Vehicles from 1940s to mid-2000s -> /", "1,700+ vehicles on site -> /"], "company_type": "Retailer", "makes_products": "no", "type_evidence": "provides a wide selection of auto parts and motorcycle parts at savings up to 80% off other auto part store prices. Our business is simple, we provide 1700+ vehicles for parts and you provide the tools and labor.", "founded_year": "1937", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='andersen-self-service-auto-parts'