UPDATE companies SET description='Based in Randolph, Wisconsin, Barn & Beam Handcrafted Tables operates a showroom and workshop The company produces a line of dining tables, benches, chairs, stools, and table bases crafted from reclaimed barn beams and hand-welded metal. Barn & Beam sells directly to consumers through its appointment-only showroom and website, offering free in-home delivery within Wisconsin and a 20 percent discount for in-store pickup. The business emphasizes handcrafted construction, using reclaimed materials and hand-welded metal bases, and operates by appointment to provide personalized service.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Handcrafted woodworking", "Hand welding of metal bases", "Furniture finishing", "In-home delivery (Wisconsin)", "Appointment-based showroom consultations"], "industries": [], "materials": ["Reclaimed barn beam wood", "Iron/steel", "Wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Free in-home delivery on all items in Wisconsin", "20% discount for in-store pickup", "Appointment-only showroom", "Handcrafted from reclaimed barn beams", "Hand-welded metal bases"], "facts_used": ["Company name and location -> db", "Address: 139 Stark St Randolph WI 53956 -> /", "Product listings: Reclaimed X-Base Iron Rail Table, Reclaimed Barn Beam Double Trestle Table, Hand Welded Metal X-Base Dining Table, etc. -> /", "Free in-home delivery in Wisconsin -> /", "20% off for in-store pickup with promo code PICKUP -> /", "Appointment-only showroom -> /", "Handcrafted and hand-welded descriptions -> /", "Materials: reclaimed barn beam, iron rail, metal -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Reclaimed Barn Beam Double Trestle Table; Hand Welded Metal X-Base Dining Table", "founded_year": "", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='barn-beam-handcrafted-tables' AND approved AND profile IS NULL;
UPDATE companies SET description='Baseline Contract Sewing operates from a manufacturing facility in Lafayette, Colorado. The company was founded in 1989 as Sportwaves Unlimited by Herbert Riehl and LeeAnn Staples, initially producing athletic bags for baseball, softball, and soccer. Within a year, the partners expanded into contract manufacturing, sewing, and print production. Herbert Riehl remains the founder and guiding force behind the business.

The shop provides full-service cut-and-sew manufacturing, including stack cutting, web cutting, die cutting, and hot and cold webbing and Velcro cutting. Precision sewing handles small runs through large-scale production. In-house design and prototyping cover pattern work, technical design, material sourcing, and design optimization. Printing and branding capabilities span DTF (Direct-to-Film), screen printing, dye-sublimation, heat-press, and vinyl applications. The facility also performs inspection, quality control, packaging, fulfillment, and hardware installation such as snaps, grommets, rivets, and eyelets.

Baseline serves clients ranging from local Colorado startups to nationwide brands. Its industry experience includes medical and technical textiles, outdoor gear—such as a custom backpack developed for an outdoor gear startup—and athletic bags. The company emphasizes adaptability across a wide variety of products and industries.

The company cites its 35-plus years of operation, local roots, and a dedicated team as foundations of its reliability. It highlights made-in-Colorado, made-in-USA production, fast turnarounds, proactive communication, and a rigorous multi-point inspection process. Clients have stayed for decades, attributing loyalty to transparent processes and a policy of never cutting corners.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Contract sewing", "Stack cutting", "Web cutting", "Die cutting", "Hot and cold webbing cutting", "Velcro cutting", "Precision sewing", "In-house product design & prototyping", "Pattern work & technical design", "Production line optimization", "Material specifying & sourcing", "DTF (Direct-to-Film) printing", "Screen printing", "Dye-sublimation printing", "Heat-press printing", "Vinyl application", "Edge-to-edge decoration", "Inspection & quality control", "Packaging & fulfillment", "Snaps, grommets, rivets, eyelets setting", "Material verification", "Shipping coordination & logistics", "Fabric, foam, and specialty material handling", "Design optimization for manufacturability"], "industries": ["Medical textiles", "Technical textiles", "Outdoor gear", "Sporting goods"], "materials": ["Fabric", "Foam", "Specialty materials", "Technical fabrics", "Webbing", "Velcro", "Vinyl"], "equipment": ["Advanced cutting equipment", "Computerized cutting department", "Digital printing DTF printers", "Digital printing dye-sublimation printers", "Vinyl heat-transfer cutting equipment", "Screen printing equipment", "Heat-press equipment", "Die-cutting equipment", "Stack cutting equipment", "Web cutting equipment"], "volume": "Prototype to large-scale production", "lead_time": "Fast turnarounds (project-dependent)", "tolerances": "", "built_on": ["Over 35 years of contract sewing experience (since 1989)", "In-house design, prototyping, and pattern work", "Advanced cutting: stack, web, die, and webbing/Velcro cutting", "Full-suite printing: DTF, screen printing, dye-sublimation, heat-press, vinyl", "Made in Colorado, Made in USA with fast turnarounds and rigorous inspection"], "facts_used": ["Founded 1989 as Sportwaves Unlimited by Herbert Riehl and LeeAnn Staples -> /about-us", "Located in Lafayette, Colorado -> /", "Full-service cut and sew manufacturing including stack cutting, web cutting, die cutting -> /", "Printing services: DTF, screen printing, dye-sublimation, heat-press, vinyl -> /", "In-house design, prototyping, pattern work, material sourcing -> /", "Industries served: medical and technical textiles, outdoor gear -> /, /about-us", "Over 35 years experience, made in Colorado/USA -> /", "Key personnel: Cindy Dyke, Ramon Mares, Tim Riehl, Herbert Riehl, Patti LaFond -> /about-us", "Fast turnarounds, rigorous inspection -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "serving clients from our manufacturing facility in stunning Lafayette, CO", "founded_year": "1989", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='baseline-contract-sewing' AND approved AND profile IS NULL;
